CREATE TABLE users (
 id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, status ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE',
 xp INT UNSIGNED NOT NULL DEFAULT 0, timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kuala_Lumpur',
 last_login_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);
CREATE TABLE roles (id VARCHAR(32) PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE user_roles (user_id CHAR(36) NOT NULL, role_id VARCHAR(32) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE refresh_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL, revoked_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_refresh_expiry(expires_at));
CREATE TABLE subjects (id VARCHAR(32) PRIMARY KEY, name VARCHAR(50) NOT NULL, color VARCHAR(20) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE lessons (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, title VARCHAR(180) NOT NULL, subject_id VARCHAR(32) NOT NULL,
 language VARCHAR(32) NOT NULL, school_level VARCHAR(64) NOT NULL, visibility ENUM('PRIVATE','UNLISTED','PUBLIC') NOT NULL DEFAULT 'PRIVATE',
 status ENUM('GENERATING','READY','FAILED') NOT NULL DEFAULT 'GENERATING', schema_version INT NOT NULL DEFAULT 1,
 source_content MEDIUMTEXT NOT NULL, input_type ENUM('TEXT','TOPIC','PDF','IMAGE') NOT NULL DEFAULT 'TEXT',
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(id),
 INDEX idx_lessons_owner(user_id,status,created_at), INDEX idx_library(visibility,subject_id,language,created_at)
);
CREATE TABLE lesson_versions (id CHAR(36) PRIMARY KEY, lesson_id CHAR(36) NOT NULL, version INT NOT NULL, definition JSON NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE, UNIQUE KEY uq_version(lesson_id,version));
CREATE TABLE lesson_scenes (id CHAR(36) PRIMARY KEY, lesson_version_id CHAR(36) NOT NULL, scene_key VARCHAR(64) NOT NULL, scene_type VARCHAR(40) NOT NULL, position INT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(lesson_version_id) REFERENCES lesson_versions(id) ON DELETE CASCADE, UNIQUE KEY uq_scene(lesson_version_id,scene_key));
CREATE TABLE generation_jobs (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, lesson_id CHAR(36), input_type VARCHAR(16) NOT NULL,
 input_content MEDIUMTEXT NOT NULL, status ENUM('PENDING','PROCESSING','COMPLETED','FAILED','CANCELLED') NOT NULL DEFAULT 'PENDING',
 progress INT NOT NULL DEFAULT 0, current_step VARCHAR(255) NOT NULL DEFAULT 'Waiting to start', provider VARCHAR(32) NOT NULL,
 model VARCHAR(100), tokens_input INT NOT NULL DEFAULT 0, tokens_output INT NOT NULL DEFAULT 0, estimated_cost DECIMAL(12,6) NOT NULL DEFAULT 0,
 error_message TEXT, attempts INT NOT NULL DEFAULT 0, started_at DATETIME(3), completed_at DATETIME(3), heartbeat_at DATETIME(3),
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL, INDEX idx_queue(status,created_at), INDEX idx_jobs_owner(user_id,created_at)
);
CREATE TABLE lesson_progress (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, lesson_id CHAR(36) NOT NULL, status ENUM('IN_PROGRESS','COMPLETED') NOT NULL DEFAULT 'IN_PROGRESS', progress INT NOT NULL DEFAULT 0, best_score INT, learning_seconds INT UNSIGNED NOT NULL DEFAULT 0, completed_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_progress(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE, INDEX idx_progress_user(user_id,updated_at));
CREATE TABLE scene_progress (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, lesson_id CHAR(36) NOT NULL, scene_key VARCHAR(64) NOT NULL, completed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_scene_progress(user_id,lesson_id,scene_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, lesson_id CHAR(36) NOT NULL, scene_key VARCHAR(64) NOT NULL, score INT NOT NULL, correct_answers INT NOT NULL, total_questions INT NOT NULL, xp_earned INT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_quiz_once(user_id,lesson_id,scene_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE quiz_answers (id CHAR(36) PRIMARY KEY, attempt_id CHAR(36) NOT NULL, question_key VARCHAR(64) NOT NULL, option_key VARCHAR(64) NOT NULL, is_correct BOOLEAN NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE, UNIQUE KEY uq_answer(attempt_id,question_key));
CREATE TABLE user_xp_transactions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, lesson_id CHAR(36), reward_key VARCHAR(150) NOT NULL, amount INT NOT NULL, reason VARCHAR(100) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_reward(user_id,reward_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL);
CREATE TABLE achievements (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL, icon VARCHAR(32) NOT NULL, threshold INT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE user_achievements (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, achievement_id VARCHAR(64) NOT NULL, earned_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_badge(user_id,achievement_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(achievement_id) REFERENCES achievements(id));
CREATE TABLE learning_streaks (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL UNIQUE, current_streak INT NOT NULL DEFAULT 0, longest_streak INT NOT NULL DEFAULT 0, last_learning_date DATE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE uploaded_files (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, original_name VARCHAR(255) NOT NULL, storage_key VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes INT NOT NULL, extracted_content MEDIUMTEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE lesson_assets (id CHAR(36) PRIMARY KEY, lesson_id CHAR(36) NOT NULL, uploaded_file_id CHAR(36), kind VARCHAR(32) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE, FOREIGN KEY(uploaded_file_id) REFERENCES uploaded_files(id) ON DELETE SET NULL);
CREATE TABLE ai_usage (id CHAR(36) PRIMARY KEY, job_id CHAR(36), user_id CHAR(36) NOT NULL, provider VARCHAR(32) NOT NULL, model VARCHAR(100), tokens_input INT NOT NULL DEFAULT 0, tokens_output INT NOT NULL DEFAULT 0, estimated_cost DECIMAL(12,6) NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(job_id) REFERENCES generation_jobs(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE system_settings (id VARCHAR(100) PRIMARY KEY, value JSON NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
